{
    int score = 72;
    void *generic = &score;
    int *typed = generic;
    *typed = 80;
    printf("%d\n", score);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int values[] = {2, 4, 6};
    int *found = NULL;
    for (size_t i = 0; i < 3; i++) {
        if (values[i] == 5) {
            found = values + i;
            break;
        }
    }
    puts(found == NULL ? "Missing" : "Found");
    return 0;
}

#include <stdio.h>

void print_int(const void *data)
{
    const int *value = data;
    printf("%d\n", *value);
}

int main(void)
{
    int value = 16;
    print_int(&value);
    return 0;
}

